import { resolve } from "node:path";
import { removeRedundantCopies, scanForDuplicates } from "../src/pipeline/dedupe-scan.ts";

/**
 * Reports pixel-identical images under src/images and public/sprites.
 * With --apply, deletes redundant copies under src/images only: public/sprites is generated
 * output and is regenerated by `npm run sprites:extract`, which fails on duplicates.
 */
const ROOT = resolve(import.meta.dirname, "..");
const SOURCE_DIRECTORY = resolve(ROOT, "src/images");
const GENERATED_DIRECTORY = resolve(ROOT, "public/sprites");

async function main(): Promise<void> {
  const apply = process.argv.includes("--apply");
  const report = await scanForDuplicates([SOURCE_DIRECTORY, GENERATED_DIRECTORY]);
  console.log(`Scanned ${report.scanned} image files.`);
  if (report.duplicateGroups.length === 0) {
    console.log("No duplicates: every image has unique pixels.");
    return;
  }
  report.duplicateGroups.forEach((group) => console.log(`duplicate group: ${group.join(" == ")}`));
  if (!apply) return;
  const sourceGroups = report.duplicateGroups.filter((group) => group.every((path) => path.startsWith(SOURCE_DIRECTORY)));
  const removed = await removeRedundantCopies(sourceGroups);
  console.log(`Removed ${removed.length} redundant source copies.`);
}

main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});
